package lk.ac.sliit.ridelink.ride.infrastructure.security;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import lk.ac.sliit.ridelink.ride.infrastructure.configuration.RideProperties; import org.springframework.stereotype.Component; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.Date;
@Component public class InternalServiceTokenProvider {private final RideProperties p;public InternalServiceTokenProvider(RideProperties p){this.p=p;}public String token(){Instant now=Instant.now();return Jwts.builder().subject("ride-management-service").issuer(p.jwtIssuer()).claim("role","SERVICE").claim("token_type","SERVICE").issuedAt(Date.from(now)).expiration(Date.from(now.plusMillis(p.serviceTokenExpirationMs()))).signWith(Keys.hmacShaKeyFor(p.jwtSecret().getBytes(StandardCharsets.UTF_8))).compact();}}
